precision highp float;
uniform float time;
uniform vec4 mouse;
uniform vec2 resolution;
uniform float fxrand;
uniform sampler2D iChannel0;
uniform sampler2D iChannel1;
uniform sampler2D iChannel2;
uniform sampler2D iChannel3;
uniform int iFrame;
uniform float BPM;
uniform int pointersCount;
#define JP_POINTERS_MAX 12
uniform int lidarPointersCount;
#define JP_LIDAR_POINTERS_MAX 30
#define iTime time
#define iMouse mouse
#define iResolution vec3(resolution, 1.0)
#define iGlobalTime time
#define bpm BPM
#define texture texture2D
#define iChannelResolution(i) vec3(resolution, 1.0)
// ============================================================================
//  AGUA · CAMPO  (Buffer A)  —  simulación de la superficie
//  ---------------------------------------------------------------------------
//  Derivado del shader "Water" de Nikos Papadopoulos (4rknova), 2019
//  (Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported).
//  Adaptado al JP Shader Editor por Carlos Kernel.
//
//  QUÉ SE CONSERVÓ Y QUÉ CAMBIÓ
//   · Se conserva el corazón del original: el campo se lee a SÍ MISMO (frame
//     anterior) y el estado va EMPAQUETADO EN UN SOLO RGBA —
//        .x = estado nuevo      .y = estado anterior (un paso atrás)
//        .z = energía (nueva)   .w = 1
//     El par (.x, .y) es el que da la "velocidad" implícita: con los dos se
//     cierra la ecuación de onda sin más canales, y el pase de salida refracta
//     con (.x - 0.5) y saca la normal del gradiente de .x.
//   · El `#define STRENGTH / SPEED / MODIFIER / STEP` del original pasó a
//     UNIFORMS del panel (todos 0..1, el rango real se arma acá adentro).
//   · La inyección NO sale de una textura con un círculo blanco: entra por el
//     MOUSE, por los PUNTEROS (multi-touch, con estela) y por TODOS los puntos
//     del LIDAR (con estela entre la posición anterior .zw y la actual .xy).
//   · Se agregó .z = energía que decae sola: es la espuma del pase de salida.
//
//  ⚠ EL KERNEL DEL ORIGINAL NO SE PUDO USAR TAL CUAL (único cambio de fondo)
//  El original actualiza con
//        d += -(s0 - 0.5) * 2.0 + (s1 + s2 + s3 + s4 - 2.0);
//  El segundo término NO es el laplaciano: es la SUMA de los cuatro vecinos
//  (cada s_i = a_i + 0.5, o sea que s1+…+s4-2 = a1+…+a4). Le falta restar el
//  centro. Con esa forma, para un campo plano la ecuación característica queda
//        r² = 0.94·(4r − 2)  →  r = 4.207
//  Es decir: el campo **crece 4.2× por frame** hasta que el clamp lo clava en
//  0/1. Medido en el editor: el arrastre del mouse dejaba un remolino gigante y
//  saturado que a los 4 s NO se curaba (y apretando y manteniendo, peor).
//  Acá se usa la MISMA familia (onda discreta) con el laplaciano correcto y la
//  condición CFL:
//        a ← k · ( 2a₁ − a₀ + c²·(Σvecinos − 4·centro) ) + inyección
//  con c² ≤ 0.5 (el eigenvalor más negativo del laplaciano de 4 vecinos es −8):
//  oscila y DECAE (|r| = 0.95 con k = 0.95) en vez de explotar. La superficie
//  se mueve igual que la del original, pero se cura sola.
//
//  ⚠ NO ROMPER (si no, el agua se muere o queda una mancha que nunca se cura):
//   1. iChannel0 = ESTE MISMO pase (conexión 'self' = frame anterior).
//   2. La altura se guarda en 0..1 con 0.5 = reposo: no hace falta textura
//      float, anda igual en UNSIGNED_BYTE.
//   3. La limpieza de los primeros 60 frames (`iFrame >= 60`) y el guardia de
//      NaN son obligatorios: el target arranca con basura indefinida y un NaN
//      se propaga por el feedback y queda pegado para siempre en ese texel.
//   4. La inyección se multiplica por (1-k) — ver la nota en el bloque de
//      inyección: sin eso, un empuje sostenido satura el campo en 2 frames y
//      se ve un anillo duro. `u_amortiguar` es cuánto DURA la estela, no la
//      fuerza (la fuerza es la amplitud objetivo de cada fuente).
// ============================================================================

uniform vec4  pointers[12];        // .xy actual (px)  .zw anterior (px)
uniform vec4  lidarPointers[30];   // idem, pero .y con el 0 ARRIBA

uniform float u_fuerza;        // 0..5  fuerza de TODOS los puntos (mouse · dedos · LIDAR)
uniform float u_radio;         // 0..5  radio de la inyección (1.5 px .. 61.5 px)
uniform float u_paso;          // 0..1  STEP: separación de los vecinos (0.7 .. 3 px)
uniform float u_oleaje;        // 0..1  c² de la superficie (velocidad de la onda)
uniform float u_amortiguar;    // 0..1  MODIFIER: amortiguación (0.90 .. 0.9995)
uniform bool  u_lidar_sim;     // barrido simulado cuando NO hay sensor

// ── helpers ────────────────────────────────────────────────────────────────

// ---------------------------------------------------------------------------
// INVERT DESDE EL SHADER
// u_flipx / u_flipy espejan los puntos (LIDAR y pointers). El OTRO invert es el
// de JavaScript: el panel ID MAPPING espeja los puntos antes de subirlos, así
// que el shader los recibe ya invertidos y estos uniforms quedan en 0.
// ---------------------------------------------------------------------------
uniform bool u_flipx;
uniform bool u_flipy;

vec2 flipGl(vec2 p) {
    if (u_flipx) p.x = resolution.x - p.x;
    if (u_flipy) p.y = resolution.y - p.y;
    return p;
}

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
float ruido(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x),
               mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x), f.y);
}
// distancia de un punto al segmento ab (la estela de un dedo / de un punto)
float sdSeg(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / max(dot(ba, ba), 0.0001), 0.0, 1.0);
    return length(pa - ba * h);
}
// el campo en una uv (el vecino); fuera de pantalla se queda con el borde
float sCampo(vec2 uv) {
    return texture2D(iChannel0, clamp(uv, vec2(0.0), vec2(1.0))).x;
}
// barrido simulado: los MISMOS puntos que dibuja el pase de salida (si cambia
// acá, cambia allá: lo que se ve es lo que empuja)
vec2 puntoFantasma(float t, float i, float aspecto) {
    float a = t * 1.7 + i * 2.399963;                       // ángulo áureo
    float r = 0.17 + 0.13 * (0.5 + 0.5 * sin(t * 0.7 + i * 1.7));
    return vec2(0.5 + r * cos(a) / aspecto, 0.5 + r * sin(a));
}

void main() {
    vec2  frag    = gl_FragCoord.xy;
    vec2  p       = frag / resolution;
    float aspecto = resolution.x / resolution.y;

    vec4 c = texture2D(iChannel0, p);          // el frame anterior de este pase
    // guardia anti-basura (ver nota 3 del encabezado)
    if (!(c.x == c.x)) c.x = 0.5;
    if (!(c.y == c.y)) c.y = 0.5;
    if (!(c.z == c.z)) c.z = 0.0;

    // ── los cuatro vecinos (el mismo muestreo que el original) ─────────────
    float paso = 0.7 + u_paso * 2.3;                       // px (original: 1.5)
    vec2  e    = vec2(paso) / resolution;
    float s1 = sCampo(p - vec2(0.0, e.y));
    float s2 = sCampo(p - vec2(e.x, 0.0));
    float s3 = sCampo(p + vec2(e.x, 0.0));
    float s4 = sCampo(p + vec2(0.0, e.y));

    // ── inyección: mouse + dedos + TODOS los puntos del LIDAR ──────────────
    // ⚠ La inyección se escala por (1-k), lo que se pierde por frame. Con un
    // empuje SOSTENIDO el campo llega a un equilibrio a_ss = iny/(1-k): si iny
    // no se escala, a_ss = 1.8 ≫ 0.5 y el clamp lo clava → anillo duro y lente
    // saturada (medido). Escalada, el equilibrio es la amplitud que se pide
    // (`amp`) y u_amortiguar sólo decide CUÁNTO DURA la estela, no la fuerza.
    float k    = 0.90 + u_amortiguar * 0.0995;      // amortiguación por frame
    float perd = 1.0 - k;
    float rPx = 1.5 + u_radio * 12.0;
    float iny = 0.0;
    float energia = 0.0;

    // MOUSE (respuesta inmediata, local). En el editor `mouse.z` sólo se
    // actualiza mientras el botón está abajo y al soltar queda NEGATIVO, así
    // que el gate es `> 0.0001` (con `step(0.0, mouse.z)` el 0 contaría como
    // apretado y quedaría un chorro fijo en el centro, porque mouse.xy arranca
    // en 0.5,0.5). Si ya hay punteros por socket no se duplica el empuje.
    float sinPunteros = 1.0 - step(0.5, float(pointersCount));
    if (mouse.z > 0.0001 && sinPunteros > 0.5) {
        float w = smoothstep(rPx, rPx * 0.15, length(frag - mouse.xy));
        iny += u_fuerza * 0.40 * perd * w;
        energia = max(energia, w * u_fuerza);
    }

    // DEDOS / multi-touch: núcleo en la posición actual + estela hasta la anterior
    for (int i = 0; i < JP_POINTERS_MAX; i++) {
        if (i >= pointersCount) break;
        vec2 pa = flipGl(pointers[i].xy);              // actual   (px, y = 0 ABAJO: ya en GL)
        vec2 pb = flipGl(pointers[i].zw);              // anterior (px)
        float wA = smoothstep(rPx, rPx * 0.15, length(frag - pa));
        float wS = smoothstep(rPx * 1.7, 0.0, sdSeg(frag, pb, pa)) * 0.55;
        iny += u_fuerza * 0.40 * perd * (wA + wS);
        energia = max(energia, max(wA, wS) * u_fuerza);
    }

    // LIDAR: TODOS los puntos (hasta JP_LIDAR_POINTERS_MAX). Vienen con la y
    // con el 0 ARRIBA (los manda la app) → se espeja: resolution.y - y.
    // Nunca se recorre más de lo que declara el array (cota constante).
    if (lidarPointersCount > 0) {
        for (int i = 0; i < JP_LIDAR_POINTERS_MAX; i++) {
            if (i >= lidarPointersCount) break;
            vec2 pa = flipGl(vec2(lidarPointers[i].x, resolution.y - lidarPointers[i].y));
            vec2 pb = flipGl(vec2(lidarPointers[i].z, resolution.y - lidarPointers[i].w));
            float wA = smoothstep(rPx, rPx * 0.15, length(frag - pa));
            float wS = smoothstep(rPx * 1.8, 0.0, sdSeg(frag, pb, pa)) * 0.65;
            iny += u_fuerza * 0.40 * perd * (wA + wS);
            energia = max(energia, max(wA, wS) * u_fuerza);
        }
    } else if (u_lidar_sim) {
        // sin sensor: 3 chorros con su cola (misma parametrización que la salida)
        float t = time * 0.80;
        for (int i = 0; i < 21; i++) {
            float fi   = float(i);
            float jet  = mod(fi, 3.0);
            float cola = floor(fi / 3.0);
            vec2  pf   = puntoFantasma(t - cola * 0.055, jet, aspecto) * resolution;
            float fade = 1.0 - cola / 7.0;
            float w    = smoothstep(rPx * 0.95, rPx * 0.15, length(frag - pf)) * fade;
            iny += u_fuerza * 0.40 * perd * w;
            energia = max(energia, w * u_fuerza);
        }
    }

    // ── la onda (ver el encabezado: laplaciano correcto + CFL) ─────────────
    float a1  = c.x - 0.5;                          // altura (t-1)
    float a0  = c.y - 0.5;                          // la de antes (t-2)
    float lap = (s1 + s2 + s3 + s4) - 4.0 * c.x;    // laplaciano de la altura
    float c2  = 0.05 + u_oleaje * 0.45;             // c² ≤ 0.5 (CFL)
    float a   = (2.0 * a1 - a0 + c2 * lap) * k;     // k = amortiguación (arriba)
    a += iny;
    a *= smoothstep(0.9, 1.0, float(iFrame >= 60)); // limpia el buffer al arrancar
    if (!(a == a)) a = 0.0;                         // un NaN quedaría pegado para siempre
    a  = clamp(a, -0.5, 0.5);

    // energía (espuma): decae sola; si hay inyección nueva, manda la nueva
    float en = clamp(max(c.z * 0.965, energia), 0.0, 1.5);

    gl_FragColor = vec4(a + 0.5, c.x, en, 1.0);     // .x altura · .y anterior · .z energía
}

precision highp float;
uniform float fxrand;
uniform sampler2D iChannel1;
uniform sampler2D iChannel2;
uniform sampler2D iChannel3;
uniform int iFrame;
uniform float BPM;
uniform int pointersCount;
#define JP_POINTERS_MAX 30
uniform int lidarPointersCount;
#define JP_LIDAR_POINTERS_MAX 30
#define iTime time
#define iMouse mouse
#define iResolution vec3(resolution, 1.0)
#define iGlobalTime time
#define bpm BPM
#define texture texture2D
#define iChannelResolution(i) vec3(resolution, 1.0)
/* ============================================================================
   texweek · PASE buffer1 — METABALLS (rascado en raymarching) ENCIMA DEL AGUA
   ----------------------------------------------------------------------------
   Viene del shader tecweekmetaballs2: 4 esferas SDF unidas con smooth-min y
   material cromado/iridiscente. Acá:
     · iChannel0 = buffer0 (el agua de texweek) → se usa como ENVIRONMENT MAP:
       las esferas reflejan el fluido en vez de un cielo cualquiera.
     · u_speed → u_meta_speed (texweek ya tenía u_speed para el agua).
     · la salida va premultiplicada por la cobertura y con alpha 1 (ver el final
       del archivo): el main compone esto ENCIMA del agua.
   ============================================================================ */
#ifdef GL_ES

#endif

// --- UNIFORMS NATIVOS ---
uniform vec2 resolution;
uniform float time;
uniform sampler2D iChannel0;

// --- SLIDERS DE GEOMETRÍA Y CÁMARA (Rango 0.0 a 1.0) ---
uniform float u_sphereSize;   // 0.0 a 1.0 directo
uniform float u_camZ;         // Posición Z de la cámara (Zoom)
uniform float u_moveRadius;     // 0..5  multiplicador del radio máximo (0 = todas al centro)   
uniform float u_meta_speed;        
uniform float u_smoothness;   

// --- SLIDERS DE MATERIAL (Rango 0.0 a 1.0) ---
uniform float u_metalness;    
uniform float u_roughness;    
uniform float u_envMix;          // mezcla de paleta propia + reflejo del entorno
uniform float u_fresnelPower; 
uniform float u_fresnelInt;   
uniform float u_iridescence;  
uniform float u_specIntensity;

// --- SLIDERS / PICKERS DE COLOR ---
uniform vec3 u_colorBase;     
uniform vec3 u_colorChrome1;  
uniform vec3 u_colorChrome2;  
uniform vec3 u_colorChrome3;  

// --- LIDAR Y MOUSE: de acá salen las posiciones de las metaballs ---
// ══ SWITCHES (todos juntos, arriba de todo) ═══════════════════════════════
uniform bool  u_track;             // trackeo ON/OFF: apaga las bolas de punteros y de LIDAR
uniform bool  u_showLidar;         // una metaball por punto del LIDAR
uniform bool  u_showMouse;         // una metaball por cada puntero (mouse/touch/socket)

// ══ PUNTOS: los DOS arrays, con los MISMOS ejes (px, y = 0 ARRIBA) ═════════
uniform vec4  lidarPointers[30];   // .xy actual · .zw anterior   (global del LIDAR)
uniform vec4  pointers[30];        // .xy actual · .zw anterior   (socket / multiusuario)
uniform vec4  mouse;               // .xy px de GL (y = 0 abajo) · .z = 1 apretado
// OJO: `lidarPointersCount` / `pointersCount` los inyecta el header (js/lib/jp-pointers.js):
// declararlos acá los hacía aparecer como sliders en la UI.

// ══ VALORES ═══════════════════════════════════════════════════════════════
uniform float u_ptr_size;          // TAMAÑO ÚNICO de las bolas de trackeo (LIDAR y punteros)
uniform float u_puntosZ;           // 0..1  profundidad Z de TODOS los puntos (mouse · dedos · LIDAR)
uniform float u_lidarK;            // fusión (más alto = puente más viscoso)

// Cámara del pase. En RETRATO (celular) se aleja: la escena está compuesta
// para apaisado y si no, las esferas se comen toda la pantalla.
float sceneCamZ() {
    float aspecto = resolution.x / resolution.y;
    float wide    = smoothstep(0.45, 1.05, aspecto);   // 0 = retrato · 1 = apaisado
    return mix(1.2, 6.0, u_camZ) * mix(1.9, 1.0, wide);
}

// píxeles → coordenada del rayo (mismo espacio que `uv` en main)

// ---------------------------------------------------------------------------
// INVERT DESDE EL SHADER
// u_flipx / u_flipy espejan los puntos (LIDAR y pointers). El OTRO invert es el
// de JavaScript: el panel ID MAPPING espeja los puntos antes de subirlos, así
// que el shader los recibe ya invertidos y estos uniforms quedan en 0.
// ---------------------------------------------------------------------------
uniform bool u_flipx;
uniform bool u_flipy;

vec2 flipGl(vec2 p) {
    if (u_flipx) p.x = resolution.x - p.x;
    if (u_flipy) p.y = resolution.y - p.y;
    return p;
}

vec2 screenUv(vec2 px) { return (px - 0.5 * resolution) / resolution.y; }

const float PI = 3.14159265359;

// Smooth Minimum Polinomial
float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// Mapeo Esférico para iChannel0
vec2 envMapUV(vec3 dir) {
    vec3 d = normalize(dir);
    float u = atan(d.z, d.x) / (2.0 * PI) + 0.5;
    float v = asin(clamp(d.y, -1.0, 1.0)) / PI + 0.5;
    return vec2(u, v);
}

float map(vec3 p, float t) {
    // u_sphereSize va de 0.0 a 1.0 directo
    float size   = clamp(u_sphereSize, 0.0, 1.0);
    // u_moveRadius es un MULTIPLICADOR del radio máximo: 0 = las 4 esferas clavadas
    // en el centro (una sola bola) · 5 = dispersión máxima (0.70, el máximo histórico).
    float esc    = clamp(u_moveRadius, 0.0, 5.0) / 5.0;
    float radius = 0.70 * esc;
    float k      = mix(0.45, 0.80, u_smoothness);
    
    vec3 p1 = vec3(0.40, 0.22, 0.0) * esc    + vec3(sin(t * 0.7), cos(t * 0.6), sin(t * 0.4) * 0.4) * radius;
    vec3 p2 = vec3(-0.50, -0.08, 0.1) * esc  + vec3(cos(t * 0.8), sin(t * 0.5), cos(t * 0.7) * 0.4) * radius;
    vec3 p3 = vec3(-0.05, -0.50, -0.1) * esc + vec3(sin(t * 0.9), cos(t * 0.7), sin(t * 0.6) * 0.4) * radius;
    vec3 p4 = vec3(0.05, 0.05, 0.15) * esc   + vec3(sin(t * 1.1) * 1.2, cos(t * 0.9) * 1.0, sin(t * 0.8) * 0.6) * radius;
    
    float s1 = length(p - p1) - 0.65 * size;
    float s2 = length(p - p2) - 0.48 * size;
    float s3 = length(p - p3) - 0.42 * size;
    float s4 = length(p - p4) - 0.35 * size;
    
    float d = smin(s1, s2, k);
    d = smin(d, s3, k);
    d = smin(d, s4, k * 0.9);
    
    // ── UNA METABALL POR CADA PUNTO DEL LIDAR ─────────────────────────────
    // El punto llega en píxeles; se lo proyecta al plano z donde viven las
    // esferas, con la MISMA cámara del pase (rd = normalize(vec3(uv, -1.2))):
    // a distancia dz, xy = uv * dz / 1.2.
    // PROFUNDIDAD DE TODO EL SISTEMA DE PUNTOS (mouse · dedos · LIDAR).
    // 0 = bien adelante de la cámara, 1 = el plano donde viven las 4 esferas.
    float profPuntos = mix(0.74, 0.985, clamp(u_puntosZ, 0.0, 1.0));

    if (u_track && u_showLidar) {
        float camZ = sceneCamZ();
        float dz   = camZ * profPuntos;
        float rs   = 0.42 * size * clamp(u_ptr_size, 0.05, 2.0);
        for (int i = 0; i < 4; i++) {
            if (i >= lidarPointersCount) break;
            vec2 suv = screenUv(flipGl(vec2(lidarPointers[i].x, resolution.y - lidarPointers[i].y)));
            vec3 c   = vec3(suv * dz / 1.2, camZ - dz);
            d = smin(d, length(p - c) - rs, k * clamp(u_lidarK, 0.1, 2.0));
        }
    }

    // ── METABALL EN EL PUNTERO (mouse / dedo) ─────────────────────────────
    // OJO: se usa `pointers`, NO `mouse`. `mouse.xy` viene en píxeles CSS y
    // `resolution` en píxeles del CANVAS: en pantallas con escala (devicePixelRatio
    // 1.25 / 1.5 / 2) la bola caía corrida hacia el centro. `pointers` lo sube el
    // motor escalado por screenWidth/Height, así que ya viene en px del canvas.
    if (u_track && u_showMouse && pointersCount > 0) {
        float camZ = sceneCamZ();
        float dz   = camZ * profPuntos;
        float rs   = 0.50 * size * clamp(u_ptr_size, 0.05, 2.0);
        // TODOS los punteros del sistema (hasta 4, por costo del raymarch), con el
        // mismo mapeo que los del LIDAR: px con y = 0 ARRIBA → se espeja.
        for (int i = 0; i < 4; i++) {
            if (i >= pointersCount) break;
            vec2 suv = (flipGl(pointers[i].xy) - 0.5 * resolution) / resolution.y;   // y = 0 abajo (GL)
            vec3 c   = vec3(suv * dz / 1.2, camZ - dz);
            d = smin(d, length(p - c) - rs, k);
        }
    }

    return d;
}

vec3 calcNormal(vec3 p, float t) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p + e.xyy, t) - map(p - e.xyy, t),
        map(p + e.yxy, t) - map(p - e.yxy, t),
        map(p + e.yyx, t) - map(p - e.yyx, t)
    ));
}

float calcAO(vec3 p, vec3 n, float t) {
    float occ = 0.0;
    float sca = 1.0;
    for(int i = 0; i < 4; i++) {
        float h = 0.02 + 0.08 * float(i);
        float d = map(p + h * n, t);
        occ += (h - d) * sca;
        sca *= 0.75;
    }
    return clamp(1.0 - 2.2 * occ, 0.0, 1.0);
}

vec3 shadeMetaball(vec3 p, vec3 n, vec3 rd, float t) {
    vec3 v = -rd;
    vec3 r = reflect(rd, n);
    float ao = calcAO(p, n, t);
    
    // --- PALETA EXACTA DE LA IMAGEN ORIGINAL (TEC WEEK) ---
    vec3 origBase    = vec3(0.04, 0.02, 0.16);
    vec3 origCyan    = vec3(0.00, 0.96, 1.00);
    vec3 origMagenta = vec3(1.00, 0.04, 0.72);
    vec3 origPurple  = vec3(0.42, 0.18, 0.96);
    
    vec3 colBase = mix(origBase,    u_colorBase,    u_envMix);
    vec3 col1    = mix(origCyan,    u_colorChrome1, u_envMix);
    vec3 col2    = mix(origMagenta, u_colorChrome2, u_envMix);
    vec3 col3    = mix(origPurple,  u_colorChrome3, u_envMix);
    
    float metal   = mix(0.88, 1.0, u_metalness);
    float rough   = mix(0.08, 0.65, u_roughness);
    float irid    = mix(0.90, 2.20, u_iridescence);
    float fresPow = clamp(u_fresnelPower, 1.0, 8.0);   // 1 suave .. 8 filo duro
    float fresInt = mix(1.00, 1.80, u_fresnelInt);
    float specInt = mix(1.30, 2.50, u_specIntensity);

    // 1. Mapeo Cromado e Iridiscente
    float cyanZone = smoothstep(-0.25, 0.65, n.x * 0.4 + n.y * 0.7 + sin(r.z * 2.5 * irid) * 0.35);
    float magZone  = smoothstep(-0.20, 0.70, -n.y * 0.8 - n.x * 0.3 + cos(r.x * 2.0 * irid) * 0.3);
    float darkCore = smoothstep(0.1, 0.85, dot(n, v));
    
    vec3 procChrome = mix(col3, colBase, darkCore * 0.85);
    procChrome = mix(procChrome, col1, cyanZone * 0.92);
    procChrome = mix(procChrome, col2, magZone * 0.85);

    // 2. Integración con iChannel0 (Environment Map)
    vec2 uvEnv = envMapUV(r + n * 0.2);
    vec3 texEnv = texture2D(iChannel0, uvEnv).rgb;
    float texLuma = dot(texEnv, vec3(0.299, 0.587, 0.114));
    
    vec3 envColor = procChrome + (texEnv * col1 * 0.6 + texEnv * col2 * 0.6) * texLuma * (0.5 + u_envMix);
    
    // 3. Mezcla Metalness
    vec3 light1 = normalize(vec3(-0.4, 0.65, 0.8));
    vec3 light2 = normalize(vec3(0.7, -0.25, 0.6));
    vec3 light3 = normalize(vec3(0.1, 0.85, 0.45));
    
    float diff = max(dot(n, light1), 0.0) * 0.6 + max(dot(n, light2), 0.0) * 0.3;
    vec3 diffuse = mix(colBase, col3, diff);
    
    vec3 col = mix(diffuse, envColor, metal);

    // 4. Fresnel (Rim Light)
    float fresnel = pow(1.0 - max(dot(n, v), 0.0), fresPow);
    vec3 rimColor = mix(col2, col1, smoothstep(-0.5, 0.5, n.x * 0.7 + n.y * 0.5));
    col = mix(col, rimColor, clamp(fresnel * fresInt, 0.0, 1.0));

    // 5. Brillos Especulares Blancos y Cian
    float specExp = mix(90.0, 10.0, rough);
    vec3 h1 = normalize(light1 + v);
    vec3 h2 = normalize(light2 + v);
    vec3 h3 = normalize(light3 + v);
    
    float spec1 = pow(max(dot(n, h1), 0.0), specExp * 0.5);
    float spec1_core = smoothstep(0.955 - rough * 0.08, 0.985, max(dot(n, h1), 0.0));
    
    float spec2 = pow(max(dot(n, h2), 0.0), specExp * 0.4);
    float spec3 = pow(max(dot(n, h3), 0.0), specExp * 0.8);
    float spec3_core = smoothstep(0.96 - rough * 0.08, 0.99, max(dot(n, h3), 0.0));
    
    col += col1 * (spec1 * 0.85 + spec2 * 0.6) * specInt;
    col += vec3(1.0, 0.98, 1.0) * (spec1_core * 0.95 + spec3 * 0.5 + spec3_core * 0.8) * specInt;
    
    col *= mix(0.35, 1.0, ao);

    return col;
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * resolution.xy) / resolution.y;
    
    float spd = mix(0.6, 2.5, u_meta_speed);
    float t = time * spd;
    
    vec3 bg = vec3(0.0);
    vec3 col = bg;
    
    // Control del eje Z de la cámara: un slider de 0.0 a 1.0 mueve Z de 1.2 (bien cerca) a 6.0 (lejos)
    float camZ = sceneCamZ();
    vec3 ro = vec3(0.0, 0.0, camZ);
    vec3 rd = normalize(vec3(uv, -1.2));
    
    float tMax = 12.0;
    float dTotal = 0.0;
    bool hit = false;
    
    for(int i = 0; i < 90; i++) {
        vec3 p = ro + rd * dTotal;
        float d = map(p, t);
        if(d < 0.001) {
            hit = true;
            break;
        }
        if(dTotal > tMax) break;
        dTotal += d;
    }
    
    // ── SALIDA PARA COMPONER EN EL PASE main ─────────────────────────────
    // Los targets de los pases NO se limpian y el renderer mezcla con SRC_ALPHA:
    // si este pase escribiera alpha < 1 quedaría un fantasma del frame anterior.
    // Entonces: alpha = 1 SIEMPRE y el color va PREMULTIPLICADO por la cobertura
    // (negro donde no hay esfera). El main recupera la máscara del brillo.
    vec3 outCol = vec3(0.0);
    if (hit) {
        vec3 p = ro + rd * dTotal;
        vec3 n = calcNormal(p, t);
        vec3 metaballColor = shadeMetaball(p, n, rd, t);
        float cov = smoothstep(0.0, 0.12, dot(n, -rd));   // antialias del borde
        outCol = metaballColor * cov;
    }

    gl_FragColor = vec4(clamp(outCol, 0.0, 1.0), 1.0);
}

precision highp float;
uniform float time;
uniform vec4 mouse;
uniform vec2 resolution;
uniform float fxrand;
uniform sampler2D iChannel0;
uniform sampler2D iChannel1;
uniform sampler2D iChannel2;
uniform sampler2D iChannel3;
uniform int iFrame;
uniform float BPM;
uniform int pointersCount;
#define JP_POINTERS_MAX 30
uniform int lidarPointersCount;
#define JP_LIDAR_POINTERS_MAX 30
#define iTime time
#define iMouse mouse
#define iResolution vec3(resolution, 1.0)
#define iGlobalTime time
#define bpm BPM
#define texture texture2D
#define iChannelResolution(i) vec3(resolution, 1.0)
// ============================================================================
//  TEXWEEK — agua sobre malla + DISPLACE del fondo  (Output)
//  ---------------------------------------------------------------------------
//  MIX de dos shaders del editor:
//    · `malla-crepusculo`  → el FONDO (seis fuentes pastel que derivan/giran)
//    · `agua-nikos`        → la SUPERFICIE encima (onda + refracción + luces)
//
//  La clave del mix: la malla se EVALÚA en la posición corrida, así el agua
//  deforma de verdad el degradé de fondo (no es un velo encima).
//
//  DISPLACE (u_disp_x / u_disp_y): el CAMPO DEL FLUIDO se usa como mapa de
//  desplazamiento del fondo, igual que un nodo Displace: la textura (la malla)
//  se corre según la altura del agua. En reposo (altura = 0.5) no corre nada;
//  cuando hay ondas, el degradé se estira y se pliega con ellas.
//
//  iChannel0 = Buffer A (el campo del agua: .x altura · .y anterior · .z energía)
//  Sin imágenes de entrada: el fondo es 100% procedural (la malla).
//
//  Derivados: "Water" de Nikos Papadopoulos (4rknova, CC BY-NC-SA 3.0) y el
//  mesh gradient propio (malla-crepusculo). Adaptación: Carlos Kernel.
// ============================================================================
uniform vec4  lidarPointers[30];   // .xy actual (px)  .zw anterior (px) — .y = 0 ARRIBA

uniform bool  u_lidar;         // MODO LIDAR: el agua se apaga y manda la nube
uniform bool  u_lidar_sim;     // barrido simulado cuando NO hay sensor

uniform float u_refraccion;    // 0..1  cuánto desvía la superficie
uniform float u_relieve;       // 0..1  relieve (pendiente de la normal)
uniform float u_profundidad;   // 0..1  profundidad (componente z de la normal)
uniform float u_especular;     // 0..1  dureza del brillo
uniform float u_brillo;        // 0..1  intensidad del brillo
uniform float u_espuma;        // 0..1  espuma donde hubo empuje
uniform float u_radio;         // 0..5  radio de los puntos del LIDAR (2px .. 122px)
uniform float u_fuerza;        // 0..5  misma fuerza que el agua: brillo de los puntos
uniform vec2  u_foco;          // posición de la luz (pad XY)
uniform vec3  u_agua;          // WATER_COLOR del original: tinte del agua
uniform float u_tinte;         // 0..1  cuánto tiñe el agua al fondo (0 = malla pura)
uniform vec4  pointers[30];      // puntero en px del canvas (.y = 0 abajo)

uniform float u_disp_x;        // 0..1  DISPLACE horizontal del fondo (fluido como mapa)
uniform float u_disp_y;        // 0..1  DISPLACE vertical del fondo

// ── malla-crepusculo: el fondo ──────────────────────────────────────────────
uniform vec3  uColorA;         // cian
uniform vec3  uColorB;         // azul-violeta
uniform vec3  uColorC;         // púrpura (domina el centro)
uniform vec3  uColorD;         // lavanda
uniform vec3  uColorE;         // durazno
uniform vec3  uColorF;         // salmón
uniform float uVelocidad;      // velocidad de la vida de la malla
uniform float uDeriva;         // cuánto se mueven las fuentes
uniform float uRespiro;        // cuánto respiran los radios
uniform float uRadio;          // zoom de la malla (1 = encuadre original)
uniform float uGiro;           // giro lento del campo
uniform float uContraste;      // profundidad de los colores
uniform float uNitidez;        // 1 = todo mezclado · 6 = cada color en su zona
uniform float uGrano;          // dithering (mata el banding)
uniform float uVignette;       // caída hacia los bordes

const vec3    SENSOR_COL = vec3(0.25, 1.0, 0.72);   // color del sensor (fijo: ya no es slider)

// ── helpers ────────────────────────────────────────────────────────────────

// ---------------------------------------------------------------------------
// INVERT DESDE EL SHADER
// u_flipx / u_flipy espejan los puntos (LIDAR y pointers). El OTRO invert es el
// de JavaScript: el panel ID MAPPING espeja los puntos antes de subirlos, así
// que el shader los recibe ya invertidos y estos uniforms quedan en 0.
// ---------------------------------------------------------------------------
uniform bool u_flipx;
uniform bool u_flipy;

vec2 flipGl(vec2 p) {
    if (u_flipx) p.x = resolution.x - p.x;
    if (u_flipy) p.y = resolution.y - p.y;
    return p;
}

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
float ruido(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x),
               mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x), f.y);
}
float sdSeg(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / max(dot(ba, ba), 0.0001), 0.0, 1.0);
    return length(pa - ba * h);
}
// barrido simulado: los MISMOS puntos que inyecta el Buffer A
vec2 puntoFantasma(float t, float i, float aspecto) {
    float a = t * 1.7 + i * 2.399963;                       // ángulo áureo
    float r = 0.17 + 0.13 * (0.5 + 0.5 * sin(t * 0.7 + i * 1.7));
    return vec2(0.5 + r * cos(a) / aspecto, 0.5 + r * sin(a));
}
// ── malla-crepusculo ──────────────────────────────────────────────────────
// Seis fuentes de luz pastel, peso gaussiano, cada una derivando y respirando.
const vec2  P_CIAN    = vec2(0.09, 0.06);
const vec2  P_VIOLETA = vec2(0.15, 0.40);
const vec2  P_PURPURA = vec2(0.46, 0.86);
const vec2  P_LAVANDA = vec2(0.06, 0.94);
const vec2  P_DURAZNO = vec2(0.98, 0.58);
const vec2  P_SALMON  = vec2(0.68, 0.05);
const float R_CIAN = 0.34, R_VIO = 0.40, R_PUR = 0.36;
const float R_LAV  = 0.34, R_DUR = 0.42, R_SAL = 0.38;
const float F_CIAN = 0.90, F_VIO = 1.05, F_PUR = 1.55;
const float F_LAV  = 1.00, F_DUR = 1.15, F_SAL = 0.75;

float hash21(vec2 p){
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec3 fuente(vec2 q, vec2 c, float radio, float fuerza, vec3 col,
            float respiro, inout float peso){
    vec2  d = q - c;
    float g = exp(-dot(d, d) / max(0.0015, radio * radio * respiro));
    float w = pow(g, clamp(uNitidez, 1.0, 8.0)) * fuerza;
    peso += w;
    return col * w;
}

// El color de la malla en una posición de PANTALLA (px): se le pasa la posición
// refractada para que el agua deforme el fondo.
vec3 malla(vec2 frag, float t){
    vec2  res    = resolution;
    float aspect = res.x / res.y;
    vec2  q = vec2(((frag.x - 0.5 * res.x) / res.y) / aspect + 0.5,
                   (frag.y - 0.5 * res.y) / res.y + 0.5);
    float vida = t * uVelocidad;
    q = (q - 0.5) / max(0.05, uRadio) + 0.5;
    float ang = vida * uGiro;
    q = 0.5 + mat2(cos(ang), -sin(ang), sin(ang), cos(ang)) * (q - 0.5);

    float dr = 0.075 * uDeriva;
    float rp = clamp(uRespiro, 0.0, 1.0);
    float peso = 0.0;
    vec3  acc  = vec3(0.0);

    acc += fuente(q, P_LAVANDA + dr * vec2(sin(vida * 0.63 + 2.1), cos(vida * 0.51 + 0.4)),
                  R_LAV, F_LAV, uColorD, 1.0 + 0.10 * rp * sin(vida * 0.68 + 2.4), peso);
    acc += fuente(q, P_PURPURA + dr * vec2(sin(vida * 0.44 + 0.7), cos(vida * 0.37 + 1.9)),
                  R_PUR, F_PUR, uColorC, 1.0 + 0.12 * rp * sin(vida * 0.41 + 0.9), peso);
    acc += fuente(q, P_CIAN + dr * vec2(sin(vida * 0.58 + 3.3), cos(vida * 0.46 + 2.6)),
                  R_CIAN, F_CIAN, uColorA, 1.0 + 0.14 * rp * sin(vida * 0.53 + 3.1), peso);
    acc += fuente(q, P_VIOLETA + dr * vec2(sin(vida * 0.35 + 1.4), cos(vida * 0.61 + 3.8)),
                  R_VIO, F_VIO, uColorB, 1.0 + 0.12 * rp * sin(vida * 0.47 + 1.6), peso);
    acc += fuente(q, P_DURAZNO + dr * vec2(sin(vida * 0.29 + 4.2), cos(vida * 0.55 + 0.9)),
                  R_DUR, F_DUR, uColorE, 1.0 + 0.10 * rp * sin(vida * 0.36 + 4.4), peso);
    acc += fuente(q, P_SALMON + dr * vec2(sin(vida * 0.67 + 0.3), cos(vida * 0.42 + 2.2)),
                  R_SAL, F_SAL, uColorF, 1.0 + 0.13 * rp * sin(vida * 0.59 + 0.2), peso);

    vec3 col = acc / max(peso, 0.0001);
    col = pow(clamp(col, 0.0, 1.0), vec3(1.0 + 0.85 * clamp(uContraste, 0.0, 1.5)));
    col *= 1.0 + 0.02 * sin(vida * 1.1);
    float v = smoothstep(0.34, 1.05, length(vec2((q.x - 0.5) * aspect, q.y - 0.5)));
    col *= 1.0 - clamp(uVignette, 0.0, 1.0) * v;
    return col;
}

uniform float u_meta;         // opacidad de los metaballs (0 = solo agua · 1 = encima)
uniform float u_meta_brillo;  // brillo de los metaballs (0.5 = neutro)

void main() {
    vec2  frag    = gl_FragCoord.xy;
    vec2  uv      = frag / resolution;
    vec2  texel   = 1.0 / resolution;
    float aspecto = resolution.x / resolution.y;

    // ── el campo del Buffer A ──────────────────────────────────────────────
    vec4 campo = texture2D(iChannel0, uv);
    vec2 tc = campo.xy;
    if (!(tc.x == tc.x)) tc.x = 0.5;
    if (!(tc.y == tc.y)) tc.y = 0.5;
    float energia = clamp(campo.z, 0.0, 1.5);
    if (!(energia == energia)) energia = 0.0;

    float h      = tc.x - 0.5;             // -0.5..0.5 : altura de la superficie (0 = reposo)
    float vel    = tc.x - tc.y;            // el cambio con el frame anterior (movimiento)
    if (!(h == h)) h = 0.0;
    if (!(vel == vel)) vel = 0.0;

    // ── normal: gradiente ESPACIAL de la altura = la pendiente ─────────────
    vec2 tx = vec2(texel.x, 0.0);
    vec2 ty = vec2(0.0, texel.y);
    vec4 mL = texture2D(iChannel0, clamp(uv - tx, vec2(0.0), vec2(1.0)));
    vec4 mR = texture2D(iChannel0, clamp(uv + tx, vec2(0.0), vec2(1.0)));
    vec4 mD = texture2D(iChannel0, clamp(uv - ty, vec2(0.0), vec2(1.0)));
    vec4 mU = texture2D(iChannel0, clamp(uv + ty, vec2(0.0), vec2(1.0)));
    vec2 grad = vec2(mR.x - mL.x, mU.x - mD.x) * 0.5;
    vec2 pend = grad * vec2(aspecto, 1.0) * (30.0 + u_relieve * 170.0);
    vec3 n    = normalize(vec3(-pend, 0.25 + u_profundidad * 1.75));

    // ── refracción: el desplazamiento es (tc - 0.5), como el original ──────
    // (el original lo usa tal cual a escala 1: acá se puede bajar, porque con
    //  un disco grande el campo llegaba a 1.0 y se veía una lente gigante)
    vec2 off = (tc - vec2(0.5)) * (0.15 + u_refraccion * 1.5);
    vec2 quv = uv + off;

    // ── FONDO: la malla evaluada en la posición REFRACTADA ─────────────────
    // (por eso el oleaje mueve los colores del degradé y no queda un velo)
    // ── DISPLACE del FONDO usando el FLUIDO como mapa ─────────────────────
    // La altura del campo (0.5 = reposo) corre la textura de fondo. Se promedia
    // con 4 vecinos porque el campo es de 8 BITS: sin suavizar, el displace deja
    // escalones (iso-contornos de la cuantización).
    vec2 t15 = texel * 1.5;
    float mapa = (h
        + (texture2D(iChannel0, clamp(uv + vec2(t15.x, 0.0), vec2(0.0), vec2(1.0))).x - 0.5)
        + (texture2D(iChannel0, clamp(uv - vec2(t15.x, 0.0), vec2(0.0), vec2(1.0))).x - 0.5)
        + (texture2D(iChannel0, clamp(uv + vec2(0.0, t15.y), vec2(0.0), vec2(1.0))).x - 0.5)
        + (texture2D(iChannel0, clamp(uv - vec2(0.0, t15.y), vec2(0.0), vec2(1.0))).x - 0.5)) * 0.2;
    // (ganancia 50: las alturas típicas del campo son ±0.002, con menos se pierde)
    // la refracción propia del agua va chica y aparte (sobre un degradé suave,
    // el desplazamiento grande del campo lo convertía en una mancha)
    vec2 quvFondo = uv + off * 0.07 + mapa * vec2(u_disp_x, u_disp_y) * 50.0;


    vec3 fondo = malla(quvFondo * resolution, time);

    // ── agua: tinte del original, pero SIN comerse los pasteles de la malla
    // (u_agua es casi blanco: con u_tinte bajo la malla manda, con 1 se tiñe)
    // La PENDIENTE de la superficie modula el brillo del fondo: sobre un piso
    // oscuro (el original) el agua se lee por el brillo especular; sobre un
    // degradé CLARO hace falta que la onda sombree, si no todo queda en velo.
    // La pendiente se mide con paso de 3 texels: el campo del agua es de 8 bits y
    // la diferencia entre vecinos INMEDIATOS está dominada por la cuantización
    // (escalones duros en el sombreado). A 3 texels la señal de la onda supera
    // al ruido y el relieve se lee suave.
    vec2 t3 = texel * 3.0;
    float hL = texture2D(iChannel0, clamp(uv - vec2(t3.x, 0.0), vec2(0.0), vec2(1.0))).x;
    float hR = texture2D(iChannel0, clamp(uv + vec2(t3.x, 0.0), vec2(0.0), vec2(1.0))).x;
    float hD = texture2D(iChannel0, clamp(uv - vec2(0.0, t3.y), vec2(0.0), vec2(1.0))).x;
    float hU = texture2D(iChannel0, clamp(uv + vec2(0.0, t3.y), vec2(0.0), vec2(1.0))).x;
    float inclina = smoothstep(0.0040, 0.0200, length(vec2(hR - hL, hU - hD)) * 0.5);
    float sombra = mix(1.02, 0.88, inclina);   // sutil: mancha si satura
    vec3 col = fondo * sombra * mix(vec3(1.0), u_agua * 1.7, clamp(u_tinte, 0.0, 1.0));

    // ── luz en las CRESTAS ─────────────────────────────────────────────────
    // Sin patrones procedurales: sale de la ALTURA del fluido (0.5 = reposo),
    // así lo único que se ve encima de la malla es el agua.
    float cresta = smoothstep(0.500, 0.522, tc.x);
    col += cresta * mix(u_agua, vec3(0.85, 0.97, 1.0), 0.6) * 0.55;

    // ── espuma: sólo donde de verdad hubo empuje (energía del Buffer A) ────
    float espN = ruido(vec2(uv.x * aspecto, uv.y) * 90.0 + vec2(time * 0.35, -time * 0.3) + vel * 30.0);
    float esp  = smoothstep(0.30, 0.95, energia)
               * smoothstep(0.45, 0.95, espN * 0.55 + energia * 0.7);
    col += esp * u_espuma * vec3(0.93, 0.98, 1.0) * 0.7;

    // ── especular: la luz es el pad `u_foco` (el original lo tenía comentado
    //    porque necesitaba una textura de entorno en iChannel2) ─────────────
    vec3  L    = normalize(vec3((u_foco - uv) * vec2(aspecto, 1.0), 0.55));
    vec3  Hv   = normalize(L + vec3(0.0, 0.0, 1.0));
    float nh   = max(dot(n, Hv), 0.0);
    float fres = pow(1.0 - clamp(n.z, 0.0, 1.0), 3.0);
    col += (pow(nh, 10.0 + u_especular * 380.0) * u_brillo * 1.8
          + pow(nh, 8.0) * u_brillo * 0.10) * vec3(1.0, 0.99, 0.96);
    col += fres * u_brillo * 0.35 * mix(u_agua, vec3(0.85, 0.97, 1.0), 0.5);

    // ── MODO LIDAR ─────────────────────────────────────────────────────────
    if (u_lidar) {
        // el agua se apaga y se oscurece: manda la lectura del sensor
        float lum = dot(col, vec3(0.333));
        col = mix(col, vec3(lum) * vec3(0.28, 0.70, 1.06) * 0.55, 0.62);

        vec3 sensor = vec3(0.0);

        // TODOS los puntos: núcleo + halo + estela (de la posición anterior a la actual)
        float rPunto = 2.0 + u_radio * 24.0;
        for (int i = 0; i < JP_LIDAR_POINTERS_MAX; i++) {
            if (i >= lidarPointersCount) break;
            vec2 act = flipGl(vec2(lidarPointers[i].x, resolution.y - lidarPointers[i].y));
            vec2 ant = flipGl(vec2(lidarPointers[i].z, resolution.y - lidarPointers[i].w));
            float dAct = length(frag - act);
            float dSeg = sdSeg(frag, act, ant);
            float nucleo = exp(-pow(dAct / (rPunto * 0.42), 2.0) * 2.2);
            float halo   = exp(-dAct / (rPunto * 1.25)) * 0.20;
            float estela = exp(-pow(dSeg / (rPunto * 0.35), 2.0)) * 0.55;
            sensor += (SENSOR_COL + vec3(0.35) * pow(nucleo, 2.0)) * (nucleo + halo + estela);
        }

        // sin sensor: el barrido simulado se DIBUJA (los mismos puntos que empujan)
        if (u_lidar_sim && lidarPointersCount == 0) {
            float t = time * 0.80;
            for (int i = 0; i < 21; i++) {
                float fi   = float(i);
                float jet  = mod(fi, 3.0);
                float cola = floor(fi / 3.0);
                vec2  pf   = puntoFantasma(t - cola * 0.055, jet, aspecto);
                float dd   = length((pf - uv) * vec2(aspecto, 1.0)) * resolution.y;
                float fade = 1.0 - cola / 7.0;
                sensor += SENSOR_COL
                        * (exp(-pow(dd / 4.5, 2.0) * 2.0) + exp(-dd / 10.0) * 0.16)
                        * fade * 1.6;
            }
        }

        // líneas de nivel de la superficie: el mapa de profundidad del sensor
        float nivel = fract((h * 1.2 + 0.5) * 3.5 + time * 0.04);
        sensor += SENSOR_COL * smoothstep(0.88, 1.0, nivel)
                * (0.05 + 0.20 * clamp(abs(h) * 2.5, 0.0, 1.5));

        // compresión por densidad: con 30 puntos encima no se ve la nube
        sensor /= 1.0 + sqrt(max(float(lidarPointersCount), 0.0)) * 0.12;
        col += sensor * (0.9 + clamp(u_fuerza, 0.0, 5.0) * 0.32);
    }

    // ── cierre: viñeta, tonemap suave, grano (mata el banding de los degradés)
    col *= 1.0 - 0.55 * length(uv - 0.5);
    col  = 1.0 - exp(-col * 1.15);
    col += (hash12(frag + fract(time) * 137.0) - 0.5) * 0.012;
    col += (hash21(frag) - 0.5) * (1.0 / 255.0) * clamp(uGrano, 0.0, 4.0);   // dithering de la malla

    // ── METABALLS ENCIMA DEL AGUA (pase buffer1) ─────────────────────────────
    // El pase escribe el color premultiplicado por su cobertura sobre negro, con
    // alpha 1 (los targets no se limpian y el renderer mezcla por SRC_ALPHA). Acá
    // la máscara sale del brillo: 0 = no hay esfera; >0.02 = esfera (el fondo es
    // negro exacto, así que el umbral sólo afecta el antialias del borde).
    vec4 meta  = texture2D(iChannel1, gl_FragCoord.xy / resolution.xy);
    float mMax = max(max(meta.r, meta.g), meta.b);
    float mMask = clamp(smoothstep(0.0, 0.02, mMax) * clamp(u_meta, 0.0, 1.0), 0.0, 1.0);
    col = col * (1.0 - mMask) + meta.rgb * (0.5 + clamp(u_meta_brillo, 0.0, 1.0) * 1.5);

    gl_FragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
